/* 120 Studio: reusable layouts, source assets, channel profiles and publish preparation.
 * Design preview only. No provider credentials, OAuth tokens or external posting calls. */
const localId=()=>Date.now().toString(36)+'-'+Array.from(crypto.getRandomValues(new Uint8Array(12)),n=>n.toString(16).padStart(2,'0')).join('');
const baseTemplates = [
 {id:'yellow',name:'120 시그니처',category:'상품 소개',layout:'signature',bg:'#f4cc59',ink:'#292e27',accent:'#ffe9a4',subtitle:'커피 옆에, 바삭한 한 조각.'},
 {id:'green',name:'내추럴 세이지',category:'상품 소개',layout:'editorial',bg:'#e7eddf',ink:'#344d3a',accent:'#cbdabf',subtitle:'일상의 작은 순간을 더 맛있게.'},
 {id:'ivory',name:'클린 아이보리',category:'브랜드',layout:'minimal',bg:'#faf6ed',ink:'#36352e',accent:'#e6d4b5',subtitle:'120겹의 이야기, 한 조각의 즐거움.'},
 {id:'bold',name:'볼드 타이포',category:'상담 유도',layout:'bold',bg:'#29392e',ink:'#fff8df',accent:'#f5ce57',subtitle:'우리 매장에 맞는지, 함께 확인해요.'},
 {id:'split',name:'메뉴 포커스',category:'상품 소개',layout:'split',bg:'#f9f5e9',ink:'#33382a',accent:'#edbd45',subtitle:'오늘의 새로운 취향을 만나보세요.'},
 {id:'postcard',name:'카페 포스트카드',category:'브랜드',layout:'polaroid',bg:'#eadccf',ink:'#4c4138',accent:'#fcfaf4',subtitle:'당신의 오후에, 파이와 커피.'},
 {id:'berry',name:'베리 컬렉션',category:'시즌 캠페인',layout:'editorial',bg:'#efe5f3',ink:'#58345c',accent:'#dbc4e0',subtitle:'기분 좋은 달콤함을 더해요.'},
 {id:'orange',name:'시즌 스포트라이트',category:'시즌 캠페인',layout:'circle',bg:'#f9e5cf',ink:'#754328',accent:'#edab78',subtitle:'오늘을 위한, 따뜻한 한 조각.'},
 {id:'guide',name:'샵인샵 가이드',category:'상담 유도',layout:'guide',bg:'#f3f4e9',ink:'#384331',accent:'#d8e3c4',subtitle:'고객 취향부터 공간과 동선까지.'}
];
const layoutLabels={signature:'제품 중심',editorial:'에디토리얼',minimal:'넓은 여백',bold:'대형 타이포',split:'상하 분할',polaroid:'포토 프레임',circle:'원형 포인트',guide:'안내 카드'};
data.templates ||= []; data.posts ||= []; data.brand.links ||= {website:'https://120piecoffee.com',instagram:'https://www.instagram.com/120piecoffee/',kakao:'',blog:'',youtube:''}; data.brand.accounts ||= {instagram:'@120piecoffee',kakao:'',blog:'',youtube:''};
defaults.templates=[];defaults.posts=[];defaults.brand.links=structuredClone(data.brand.links);defaults.brand.accounts=structuredClone(data.brand.accounts);
navs.push(['publish','upload','게시 관리']);
let allTemplates=()=>[...baseTemplates,...data.templates];
const selectedTemplate=()=>allTemplates().find(t=>t.id===campaign().template)||baseTemplates[0];
let allAssets=()=>[...products.map(p=>({...p,role:'product',menu:p.name,tags:'실제 제품, 누끼',type:'실제 제품·서비스 사진'})),{id:'lifestyle',name:'애플파이와 라떼',img:'assets/lifestyle.webp',role:'reference',type:'생성 연출 이미지',tags:'분위기 참고'},...data.uploads.map(a=>({...a,role:a.role||'reference'}))];
const roleNames={product:'실제 제품·서비스 사진',reference:'디자인 참고',logo:'브랜드 로고'};
let templateFilter='전체',templateSearch='',assetFilter='all',templateDraft=null,uploadDraft=null;
const assetURLs=new Map(), imageCache=new Map();
function assetSource(a){return assetURLs.get(a.id)||a.img}
function dbOpen(){return new Promise((resolve,reject)=>{const r=indexedDB.open('120studio-assets',1);r.onupgradeneeded=()=>r.result.createObjectStore('originals');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
async function dbPut(id,file){const db=await dbOpen();return new Promise((resolve,reject)=>{const tx=db.transaction('originals','readwrite');tx.objectStore('originals').put(file,id);tx.oncomplete=()=>{db.close();resolve()};tx.onerror=()=>{db.close();reject(tx.error)}})}
async function restoreAssets(){if(!data.uploads.some(a=>a.original))return;try{const db=await dbOpen();await Promise.all(data.uploads.filter(a=>a.original).map(a=>new Promise(resolve=>{const r=db.transaction('originals').objectStore('originals').get(a.id);r.onsuccess=()=>{if(r.result)assetURLs.set(a.id,URL.createObjectURL(r.result));resolve()};r.onerror=resolve})));db.close();render()}catch{toast('원본 보관함에 접근하지 못했습니다. 저장된 미리보기를 표시합니다.')}}
function loadImage(src){if(!imageCache.has(src))imageCache.set(src,new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>resolve(im);im.onerror=()=>reject(Error('이미지를 읽지 못했습니다.'));im.src=src}));return imageCache.get(src)}
function wrapLines(ctx,value,width){const out=[];String(value).split('\n').forEach(p=>{let line='';for(const c of p){if(ctx.measureText(line+c).width>width&&line){out.push(line);line=c}else line+=c}out.push(line)});return out}
function fittedText(ctx,text,x,y,w,maxH,size,color,weight=800,align='left'){let lines,sz=size;do{ctx.font=`${weight} ${sz}px "Noto Sans KR", sans-serif`;lines=wrapLines(ctx,text,w);if(lines.length*sz*1.4<=maxH)break;sz-=2}while(sz>20);ctx.fillStyle=color;ctx.textAlign=align;lines.forEach((line,i)=>ctx.fillText(line,x,y+i*sz*1.4));ctx.textAlign='left'}
function contain(ctx,im,x,y,w,h){const z=Math.min(w/im.width,h/im.height);ctx.drawImage(im,x+(w-im.width*z)/2,y+(h-im.height*z)/2,im.width*z,im.height*z)}
function paintCard(cv,t,title,im,sub,index=0,total=5,format='instagram'){
 const w=1080,h=format==='kakao'?1080:1350;cv.width=w;cv.height=h;const ctx=cv.getContext('2d');ctx.fillStyle=t.bg;ctx.fillRect(0,0,w,h);ctx.fillStyle=t.ink;ctx.font='800 27px "Noto Sans KR",sans-serif';fittedText(ctx,data.brand.name.toUpperCase(),70,85,690,38,27,t.ink);ctx.font='500 18px sans-serif';ctx.fillText(isPie()?'THE GOOD LAYERS':'YOUR BRAND STORY',795,85);
 const titleText=title||data.brand.name, desc=sub||t.subtitle;let ty=205,tw=930,th=h*.26,ts=91,tx=70;
 switch(t.layout){
  case 'editorial':ctx.fillStyle=t.accent;ctx.fillRect(0,h*.47,w,h*.45);contain(ctx,im,80,h*.46,920,h*.43);ctx.strokeStyle=t.ink;ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(70,125);ctx.lineTo(1010,125);ctx.stroke();ts=86;break;
  case 'minimal':contain(ctx,im,165,h*.40,750,h*.40);ts=78;tx=540;break;
  case 'bold':ctx.fillStyle=t.accent;ctx.fillRect(50,h*.51,980,h*.38);contain(ctx,im,80,h*.51,920,h*.37);ts=99;break;
  case 'split':ctx.fillStyle=t.accent;ctx.fillRect(0,140,w,h*.46);contain(ctx,im,50,145,980,h*.44);ty=h*.69;th=h*.19;ts=78;break;
  case 'polaroid':ctx.fillStyle=t.accent;ctx.fillRect(65,145,950,h*.54);contain(ctx,im,110,175,860,h*.47);ty=h*.77;ts=69;th=h*.14;break;
  case 'circle':ctx.fillStyle=t.accent;ctx.beginPath();ctx.arc(540,h*.66,h*.27,0,Math.PI*2);ctx.fill();contain(ctx,im,70,h*.44,940,h*.43);ts=83;break;
  case 'guide':ctx.fillStyle=t.accent;ctx.fillRect(60,h*.49,960,h*.39);contain(ctx,im,350,h*.5,650,h*.37);ctx.fillStyle=t.ink;ctx.font='800 26px sans-serif';['01  소개','02  특징','03  문의'].forEach((v,i)=>ctx.fillText(v,100,h*.60+i*75));ts=87;break;
  default:ctx.fillStyle=t.accent;ctx.beginPath();ctx.arc(940,h-150,480,0,Math.PI*2);ctx.fill();contain(ctx,im,0,h*.45,1080,h*.45);
 }
 fittedText(ctx,titleText,tx,ty,tw,th,ts,t.ink,800,t.layout==='minimal'?'center':'left');
 const sy=['split','polaroid'].includes(t.layout)?h-112:ty+th+22;
 fittedText(ctx,desc,t.layout==='minimal'?540:70,sy,930,76,27,t.ink,500,t.layout==='minimal'?'center':'left');
 ctx.fillStyle=t.ink;ctx.font='500 21px sans-serif';fittedText(ctx,data.brand.name,70,h-44,800,28,21,t.ink,500);ctx.fillText(`${String(index+1).padStart(2,'0')} / ${String(total).padStart(2,'0')}`,935,h-44);
}
async function fillCanvases(){await document.fonts.ready;await Promise.all([...document.querySelectorAll('[data-art-canvas]')].map(async cv=>{try{const t=cv.dataset.templateId==='draft'?templateDraft:allTemplates().find(t=>t.id===cv.dataset.templateId)||selectedTemplate();const im=await loadImage(prod().img);if(!cv.isConnected)return;const idx=Number(cv.dataset.cardIndex||0);paintCard(cv,t,cv.dataset.demo==='yes'?(isPie()?'커피 옆에,\n바삭한 한 조각.':'새로운 가능성,\n우리의 이야기.'):campaign().titles[idx],im,t.subtitle,idx,5,cv.dataset.format||channel)}catch{cv.setAttribute('aria-label','이미지를 불러오지 못했습니다. 자료실에서 사진을 확인하세요.')}}))}
artCard=function(index=cardIndex,cls=''){return `<div class="art-card canvas-art ${cls}" id="${cls?'':'art-preview'}"><canvas data-art-canvas data-template-id="${esc(campaign().template)}" data-card-index="${index}" data-format="${channel}" role="img" aria-label="${esc(campaign().titles[index])}"></canvas></div>`};
const originalRender=render;
render=function(){originalRender();fillCanvases()};
const originalStudio=studio;
studio=function(){let html=originalStudio();const c=campaign();html=html.replace(/<select id="creation-template"[\s\S]*?<\/select>/,`<select id="creation-template" data-template-select>${allTemplates().map(t=>`<option value="${t.id}" ${c.template===t.id?'selected':''}>${esc(t.name)}</option>`).join('')}</select><button class="btn ghost sm full" data-act="template-current">${icon('plus')}현재 디자인을 템플릿으로 저장</button>`);
 html=html.replace('<div class="field"><label for="topic">',`<div class="field"><label for="studio-asset">자료실의 실제 제품·서비스 사진</label><select id="studio-asset"><option value="">기본 제품 사진 사용</option>${allAssets().filter(a=>a.role==='product').map(a=>`<option value="${a.id}" ${c.assetId===a.id?'selected':''}>${esc(a.name)}</option>`).join('')}</select><p class="hint">선택한 원본을 그대로 배치합니다. 제품 모양을 다시 그리지 않습니다.</p><button class="btn ghost sm" data-route="assets">${icon('image')}제품 사진 추가·관리</button></div><div class="field"><label for="studio-reference">분위기 참고 이미지</label><select id="studio-reference"><option value="">선택 안 함</option>${allAssets().filter(a=>a.role==='reference').map(a=>`<option value="${a.id}" ${c.referenceAssetId===a.id?'selected':''}>${esc(a.name)}</option>`).join('')}</select><p class="hint">기획 참고용으로 지정합니다. 자동 분석·디자인 생성은 API 연결 후 제공됩니다.</p></div><div class="field"><label for="topic">`);
 html=html.replace('<button class="btn primary sm" data-act="approve">', '<button class="btn sm" data-act="publish-open">게시 준비 '+icon('arrow')+'</button><button class="btn primary sm" data-act="approve">');
 return html;
};
function templateTile(t){return `<article class="template new-template"><div class="template-image"><canvas data-art-canvas data-template-id="${esc(t.id)}" data-demo="yes" data-format="instagram" role="img" aria-label="${esc(t.name)} 디자인 미리보기"></canvas><span class="badge ${t.custom?'green':'yellow'}">${t.custom?'내 템플릿':t.category}</span></div><div class="template-details"><div class="flex between"><h3>${esc(t.name)}</h3><button class="icon-btn" data-template-edit="${t.id}" aria-label="${esc(t.name)} ${t.custom?'수정':'복제'}">${icon(t.custom?'edit':'copy')}</button></div><p>${layoutLabels[t.layout]} · 피드 4:5 / 카톡 1:1</p><button class="btn full" data-use-template="${t.id}">제작실에 적용 ${icon('arrow')}</button></div></article>`}
templatesPage=function(){const list=allTemplates().filter(t=>(templateFilter==='전체'||templateFilter==='내 템플릿'&&t.custom||t.category===templateFilter)&&t.name.toLowerCase().includes(templateSearch.toLowerCase()));return `${pageHead('디자인 템플릿','좋은 디자인은 쌓아두고, 새로운 이야기에 다시 꺼내 쓰세요.',`<button class="btn primary" data-act="template-new">${icon('plus')}템플릿 추가</button>`,'DESIGN COLLECTION')}<div class="collection-banner"><div><span class="eyebrow">YOUR BRAND. MORE POSSIBILITIES.</span><h2>매번 새롭게, 언제나 우리답게.</h2><p>기본 템플릿 ${baseTemplates.length}종과 나만의 디자인. 색상·배치·기본 문구를 저장해 재사용하세요.</p></div><div class="collection-count"><b>${allTemplates().length}</b><span>개의 디자인</span></div></div><div class="collection-toolbar"><div class="filter-chips">${['전체','상품 소개','상담 유도','브랜드','시즌 캠페인','내 템플릿'].map(f=>`<button class="${f===templateFilter?'active':''}" data-t-filter="${f}">${f}${f==='내 템플릿'?` ${data.templates.length}`:''}</button>`).join('')}</div><div class="search-box">${icon('search')}<input type="text" id="template-search" aria-label="템플릿 검색" placeholder="템플릿 이름 검색" value="${esc(templateSearch)}"></div></div><div class="template-grid" id="template-results">${list.map(templateTile).join('')||'<div class="empty">아직 템플릿이 없어요. 새 디자인을 추가해 보세요.</div>'}</div><p class="settings-note">템플릿은 이미지 카드용입니다. 영상 장면·자막 편집은 콘텐츠 제작실에서 별도로 진행합니다.</p>`};
function openTemplate(id,fromCurrent=false){const src=allTemplates().find(t=>t.id===id)||selectedTemplate();templateDraft={...src,id:src.custom&&!fromCurrent?src.id:'custom-'+localId(),name:fromCurrent?src.name+' · 내 디자인':id?(src.custom?src.name:src.name+' 복사본'):'나만의 새 템플릿',custom:true};openModal(src.custom&&!fromCurrent?'템플릿 수정':'나만의 템플릿 추가',`<div class="template-editor"><div><div class="field"><label for="tpl-name">템플릿 이름</label><input id="tpl-name" type="text" maxlength="40" value="${esc(templateDraft.name)}" data-tpl="name"></div><div class="field"><label for="tpl-category">콘텐츠 목적</label><select id="tpl-category" data-tpl="category">${['상품 소개','상담 유도','브랜드','시즌 캠페인'].map(x=>`<option ${x===src.category?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label for="tpl-layout">레이아웃</label><select id="tpl-layout" data-tpl="layout">${Object.entries(layoutLabels).map(([id,n])=>`<option value="${id}" ${id===src.layout?'selected':''}>${n}</option>`).join('')}</select></div><div class="color-fields">${[['bg','배경'],['ink','글자'],['accent','포인트']].map(([k,l])=>`<label>${l}<input type="color" value="${src[k]}" data-tpl="${k}" aria-label="${l} 색상"></label>`).join('')}</div><div class="field"><label for="tpl-sub">기본 보조 문구</label><input id="tpl-sub" type="text" maxlength="65" data-tpl="subtitle" value="${esc(src.subtitle)}"></div></div><div class="template-live"><canvas data-art-canvas data-template-id="draft" data-demo="yes" data-format="instagram" role="img" aria-label="편집 중인 템플릿 미리보기"></canvas><small>문구·사진은 캠페인마다 바꿀 수 있어요.</small></div></div>`,`<button class="btn" data-act="close-modal">취소</button><button class="btn primary" data-act="template-save">템플릿 저장</button>`);$('.modal').classList.add('wide-modal');fillCanvases()}
assetsPage=function(){const list=allAssets().filter(a=>assetFilter==='all'||a.role===assetFilter);return `${pageHead('브랜드 자료실','실제 제품의 모습은 지키고, 디자인의 가능성은 넓혀요.',`<button class="btn primary" data-act="asset-add">${icon('upload')}이미지 추가</button>`)}<div class="asset-guidance"><div><span class="step-number">01</span><strong>실제 제품·서비스 사진</strong><p>제품 원본을 콘텐츠에 직접 배치</p></div><div><span class="step-number">02</span><strong>디자인 참고</strong><p>색감·구도·분위기의 기준으로 지정</p></div><div><span class="step-number">03</span><strong>제작실에 적용</strong><p>선택한 사진과 템플릿으로 디자인</p></div></div><div class="collection-toolbar"><div class="filter-chips">${[['all','전체'],['product','실제 제품·서비스 사진'],['reference','디자인 참고'],['logo','로고']].map(([id,n])=>`<button class="${assetFilter===id?'active':''}" data-a-filter="${id}">${n}</button>`).join('')}</div><div class="search-box">${icon('search')}<input id="asset-search" type="text" aria-label="자료 이름 검색" placeholder="자료 이름 검색"></div></div><div class="asset-grid">${list.map(a=>`<article class="asset" data-asset-name="${esc(a.name)}"><div class="asset-img"><img src="${assetSource(a)}" alt="${esc(a.name)}"><span class="badge ${a.role==='product'?'green':'outline'}">${a.type||roleNames[a.role]}</span></div><div class="asset-body"><h3>${esc(a.name)}</h3><p>${esc(a.menu||a.tags||'브랜드 자료')} · ${a.original?'원본 보관':'기본 자료'}</p><div class="asset-actions"><button class="btn sm" data-asset-detail="${a.id}">정보·보기</button>${a.role!=='logo'?`<button class="btn sm primary" data-asset-use="${a.id}">${a.role==='product'?'제품으로 사용':'참고로 지정'}</button>`:''}</div></div></article>`).join('')||'<div class="empty">이 분류의 이미지가 아직 없습니다.</div>'}</div><div class="notice" style="margin-top:22px">${icon('image')}사진은 이 브라우저에 보관됩니다. 업로드한 제품 원본은 그대로 사용하며, 디자인 참고 이미지의 자동 분석은 생성 API 연결 후 제공됩니다.</div>`};
function openUpload(){uploadDraft={};openModal('브랜드 이미지 추가',`<p class="intro">실제 제품 사진인지, 분위기를 참고할 이미지인지 먼저 구분해 주세요.</p><div class="field"><label for="upload-role">자료 용도</label><select id="upload-role"><option value="product">실제 제품·서비스 사진 · 제품 원본 유지</option><option value="reference">디자인 참고 · 색감과 구도 참고</option><option value="logo">브랜드 로고 · 원본 보관</option></select></div><div class="field"><label for="upload-menu">연결할 제품·서비스 이름 (선택)</label><input type="text" id="upload-menu" maxlength="60" placeholder="예: 대표 제품 또는 서비스"></div><div class="field"><label for="upload-tags">검색 태그 (선택)</label><input type="text" id="upload-tags" maxlength="100" placeholder="예: 단면, 누끼, 시즌 메뉴"></div><label class="upload-zone" for="new-asset-files">${icon('upload')}<strong>이미지 파일 선택</strong><span>PNG · JPG · WebP / 파일당 12MB 이하</span><input type="file" id="new-asset-files" accept="image/png,image/jpeg,image/webp" multiple></label><p class="settings-note">원본과 미리보기를 이 브라우저에 보관합니다. 실제 제품·서비스 사진은 형태·필링·로고를 다시 생성하지 않습니다.</p>`,`<button class="btn" data-act="close-modal">취소</button><button class="btn primary" data-act="asset-save">자료실에 추가</button>`)}
async function saveUploads(btn){const files=[...$('#new-asset-files').files];if(!files.length){toast('추가할 이미지 파일을 선택해 주세요.');return}const role=$('#upload-role').value,menu=$('#upload-menu').value.trim(),tags=$('#upload-tags').value.trim();btn.disabled=true;btn.textContent='원본 보관 중…';let added=0,errors=[];for(const f of files){if(!['image/png','image/jpeg','image/webp'].includes(f.type)||f.size>12*1024*1024){errors.push(f.name+': 형식 또는 용량 확인');continue}try{const src=URL.createObjectURL(f),im=await loadImage(src),cv=document.createElement('canvas'),z=Math.min(1,500/Math.max(im.width,im.height));cv.width=Math.round(im.width*z);cv.height=Math.round(im.height*z);cv.getContext('2d').drawImage(im,0,0,cv.width,cv.height);const id='asset-'+localId();await dbPut(id,f);assetURLs.set(id,src);data.uploads.push({id,name:f.name,menu,tags,role,type:roleNames[role],img:cv.toDataURL('image/webp',.8),original:true,width:im.width,height:im.height});if(!persist()){data.uploads.pop();errors.push(f.name+': 설정 저장 실패');continue}added++}catch{errors.push(f.name+': 원본 보관 실패')}}closeModal();navigate('assets');toast(`${added}개 이미지 추가${errors.length?' · '+errors.length+'개 실패':''}`);if(errors.length)openModal('일부 이미지를 추가하지 못했습니다',`<p class="intro">${errors.map(esc).join('<br>')}</p>`)}
function assetDetail(id){const a=allAssets().find(a=>a.id===id);if(!a)return;openModal(esc(a.name),`<img class="asset-detail-image" src="${assetSource(a)}" alt="${esc(a.name)}"><div class="field"><label>용도</label><p>${roleNames[a.role]}${a.original?' · 업로드 원본 보관':''}</p></div><p class="intro">${a.role==='product'?'콘텐츠에서 이 사진을 직접 배치합니다. 제품을 새로 그리지 않습니다.':a.role==='reference'?'디자인 방향을 위한 참고 자료입니다. 현재는 AI 분석이 실행되지 않습니다.':'브랜드 로고 원본을 보관합니다.'}</p>${a.original?`<div class="field"><label for="asset-role-edit">분류 변경</label><select id="asset-role-edit">${Object.entries(roleNames).map(([k,v])=>`<option value="${k}" ${a.role===k?'selected':''}>${v}</option>`).join('')}</select></div>`:''}`,`<button class="btn" data-act="close-modal">닫기</button>${a.original?`<button class="btn primary" data-asset-role-save="${id}">분류 저장</button>`:''}`)}
const profileChannels=[{id:'instagram',name:'인스타그램',icon:'instagram',color:'pink',method:'공식 API 연결 대상',note:'비즈니스·크리에이터 계정 및 게시 권한 필요',placeholder:'https://www.instagram.com/계정/'},{id:'kakao',name:'카카오톡 채널',icon:'chat',color:'yellow',method:'관리자에서 직접 게시',note:'카드뉴스 소식 등록과 유료 메시지 발송은 별도 작업',placeholder:'https://pf.kakao.com/채널ID'},{id:'blog',name:'네이버 블로그',icon:'blog',color:'green',method:'본문·이미지 전달',note:'글쓰기 공개 API 종료 · 관리자에서 최종 게시',placeholder:'https://blog.naver.com/블로그ID'},{id:'youtube',name:'유튜브',icon:'play',color:'red',method:'공식 API 연결 대상',note:'Google 계정 인증 및 동영상 업로드 권한 필요',placeholder:'https://www.youtube.com/@계정'}];
const profileKey=id=>id==='reels'?'instagram':id;
function linkSafe(value,id='website'){let val=(value||'').trim();if(!val)return '';if(!/^https?:\/\//i.test(val)){val='https://'+val;}let u;try{u=new URL(val);}catch{throw Error('올바른 인터넷 주소(URL)를 입력해 주세요.');}if(u.protocol==='http:'){u.protocol='https:';}if(u.protocol!=='https:'){throw Error('보안 주소(https://)로 시작하는 주소를 입력해 주세요.');}if(u.username||u.password){throw Error('주소에 계정 정보(아이디/비밀번호)를 포함할 수 없습니다. 공개 채널 주소만 입력해 주세요.');}const hosts={instagram:['instagram.com'],kakao:['pf.kakao.com'],blog:['blog.naver.com','m.blog.naver.com'],youtube:['youtube.com','youtu.be']};const channelNames={instagram:'인스타그램(instagram.com)',kakao:'카카오톡 채널(pf.kakao.com)',blog:'네이버 블로그(blog.naver.com)',youtube:'유튜브(youtube.com)'};if(hosts[id]&&!hosts[id].some(h=>u.hostname===h||u.hostname.endsWith('.'+h))){throw Error(`${channelNames[id]||'해당 채널'}의 공식 주소를 입력해 주세요.`);}return u.href;}
const oldBrandPage=brandPage;
brandPage=function(){return `${pageHead('브랜드 · 채널 설정','우리 브랜드의 기준부터 콘텐츠가 도착할 채널까지, 한곳에서 관리하세요.',`<button class="btn primary" data-act="brand-save-all">${icon('check')}변경사항 저장</button>`)}<div class="brand-settings-layout"><section class="panel"><h2>브랜드 기본 정보</h2><div class="divider"></div><div class="brand-form-grid"><div class="field"><label for="brand-name">브랜드 이름</label><input type="text" id="brand-name" maxlength="60" value="${esc(data.brand.name)}"></div><div class="field"><label for="brand-website">홈페이지 주소</label><input type="url" id="brand-website" placeholder="https://" value="${esc(data.brand.links.website||'')}"></div><div class="field wide"><label for="brand-tone">브랜드 말투</label><input id="brand-tone" type="text" value="${esc(data.brand.tone)}"></div><div class="field wide"><label for="brand-description">브랜드 소개</label><textarea id="brand-description">${esc(data.brand.description)}</textarea></div><div class="field wide"><label for="brand-cta">기본 상담 유도 문구</label><input type="text" id="brand-cta" value="${esc(data.brand.cta)}"></div></div></section><aside class="panel account-guide"><span class="badge yellow">CHANNEL CONNECTION</span><h2>주소 등록과 <br>게시 인증은 달라요.</h2><p>주소·계정명은 콘텐츠와 링크에 사용합니다. 직접 게시는 해당 채널의 별도 계정 인증이 필요합니다.</p><div class="notice">${icon('lock')}비밀번호·API 키를 이 화면에서 입력받지 않습니다.</div><p>현재 시안에서는 주소와 설정을 이 브라우저에 저장합니다. 실제 계정 인증은 아직 연결되지 않았습니다.</p></aside></div><div class="section-title" style="margin-top:28px"><div><h2>SNS 채널 계정</h2><p>인스타그램의 피드와 릴스는 같은 계정을 사용합니다.</p></div><span class="badge outline">게시 인증 0 / 2</span></div><div class="channel-profile-grid">${profileChannels.map(c=>`<section class="panel channel-profile"><div class="flex between"><div class="flex"><span class="channel-icon ${c.color}">${icon(c.icon)}</span><div><h3>${c.name}</h3><small class="muted">${c.method}</small></div></div><span class="badge ${data.brand.links[c.id]?'green':''}">${data.brand.links[c.id]?'주소 등록':'주소 미등록'}</span></div><div class="field" style="margin-top:22px"><label for="account-${c.id}">계정명 / 채널명</label><input type="text" id="account-${c.id}" maxlength="80" value="${esc(data.brand.accounts[c.id]||'')}" placeholder="계정명 또는 채널명"></div><div class="field"><label for="link-${c.id}">공개 채널 주소</label><input type="url" id="link-${c.id}" value="${esc(data.brand.links[c.id]||'')}" placeholder="${c.placeholder}"></div><p class="settings-note">${c.note}</p><div class="flex between channel-auth"><span class="badge outline">${['instagram','youtube'].includes(c.id)?'게시 권한 미연결':'직접 게시 방식'}</span><button class="btn sm" data-auth-info="${c.id}">${['instagram','youtube'].includes(c.id)?'계정 연결 안내':'게시 방식 안내'} ${icon('chevron')}</button></div></section>`).join('')}</div>`};
function authInfo(id){const key=profileKey(id),c=profileChannels.find(c=>c.id===key);openModal(`${c.name} ${['instagram','youtube'].includes(key)?'계정 연결':'게시 방식'}`,`<div class="notice">${icon('link')}${['instagram','youtube'].includes(key)?'게시 권한 미연결 · OAuth 서버 설정 필요':'공식 관리자에서 최종 게시'}</div><p class="intro" style="margin-top:20px">${key==='instagram'?'실제 개발에서는 Meta 로그인으로 비즈니스·크리에이터 계정을 선택하고 콘텐츠 게시 권한을 승인합니다. 피드와 릴스를 같은 연결로 관리합니다.':key==='youtube'?'실제 개발에서는 Google 로그인으로 업로드할 YouTube 채널을 선택하고 동영상 업로드 권한을 승인합니다. 공개 범위·아동용 여부 등은 게시 전에 확인합니다.':key==='blog'?'네이버 블로그 글쓰기 오픈 API가 종료되어, 본문과 이미지를 준비한 뒤 블로그 관리자에서 게시하는 방식입니다.': '카카오톡 채널 공개 API 문서에서는 소식 게시 기능을 확인하지 못했습니다. 카드뉴스와 본문을 준비해 채널 관리자에서 등록합니다. 유료 메시지 발송은 별도 연동과 발송 승인이 필요한 기능입니다.'}</p><p class="settings-note">현재 연결 버튼으로 외부 계정 인증을 수행하지 않습니다. 주소 등록만으로 연결 완료 상태로 바뀌지 않습니다.</p>`,`<button class="btn primary" data-act="close-modal">확인</button>`)}
function saveBrandAll(){const name=$('#brand-name').value.trim();if(!name){toast('브랜드 이름을 입력해 주세요.');return}try{const links={website:linkSafe($('#brand-website').value)},accounts={};for(const c of profileChannels){links[c.id]=linkSafe($('#link-'+c.id).value,c.id);accounts[c.id]=$('#account-'+c.id).value.trim()}const previous=data.brand;data.brand={...data.brand,name,tone:$('#brand-tone').value,description:$('#brand-description').value,cta:$('#brand-cta').value,links,accounts};if(!persist()){data.brand=previous;return}render();toast('브랜드와 채널 주소를 저장했어요. 게시 인증은 미연결 상태입니다.')}catch(err){toast(err.message)}}
function captionFor(id=channel){return campaign().channelCaptions?.[id]??campaign().caption}
function fullText(id=channel){return id==='blog'?campaign().name+'\n\n'+captionFor(id):captionFor(id)}
const oldStudio2=studio;
studio=function(){let s=oldStudio2();return s.replace(esc(campaign().caption)+'</textarea>',esc(captionFor())+'</textarea>')};
copyCaption=async function(){try{await navigator.clipboard.writeText(fullText());toast('이 채널의 본문을 복사했어요.')}catch{openModal('본문을 직접 복사해 주세요',`<textarea class="copy-fallback" readonly>${esc(fullText())}</textarea>`);$('.copy-fallback').select()}};
const managerLinks={instagram:'https://www.instagram.com/',reels:'https://www.instagram.com/',kakao:'https://center-pf.kakao.com/',blog:'https://blog.naver.com/',youtube:'https://studio.youtube.com/'};
function publishPage(){const c=campaign(),ch=channels.find(x=>x.id===channel)||channels[0],isVideo=['youtube','reels'].includes(channel),key=profileKey(channel),direct=['instagram','youtube','reels'].includes(channel),posts=data.posts.filter(p=>p.campaignId===c.id);return `${pageHead('게시 관리','완성한 콘텐츠를 확인하고, 채널에 맞는 방식으로 전달하세요.',`<button class="btn" data-route="studio">${icon('edit')}제작실로 돌아가기</button>`,'PUBLISH WORKSPACE')}<div class="publish-flow"><span class="done">${icon('check')}콘텐츠 편집</span><i></i><span class="active">02 게시 전 확인</span><i></i><span>03 채널 등록</span></div><div class="field" style="max-width:450px"><label for="publish-campaign">게시할 캠페인</label><select id="publish-campaign">${data.campaigns.map(x=>`<option value="${x.id}" ${c.id===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div><div class="tabs publish-tabs">${channels.map(x=>`<button class="tab ${channel===x.id?'active':''}" data-channel="${x.id}">${icon(x.icon)}${x.short}</button>`).join('')}</div><div class="publish-layout"><section class="panel publish-preview"><div class="flex between"><h2>${ch.name}</h2><span class="badge yellow">${isVideo?'장면표 시안':'이미지·본문 준비'}</span></div><div class="publish-art">${isVideo?`<div class="video-pending">${icon('video')}<h3>영상 완성본이 필요해요</h3><p>현재는 20초 장면표 미리보기입니다.<br>게시할 MP4 영상은 아직 생성되지 않았습니다.</p><button class="btn" data-route="studio">장면표 편집</button></div>`:artCard(0)}</div><h3>${esc(c.name)}</h3><p class="publish-caption">${esc(captionFor())}</p><div class="publish-file-row">${icon(isVideo?'video':'image')} ${isVideo?'MP4 미생성 · 장면표 TXT 제공':channel==='blog'?'대표 이미지 1장 + 본문 TXT':'카드 이미지 5장 + 본문 TXT'}</div></section><section class="panel publish-controls"><h2>게시 전 확인</h2><div class="account-summary"><span class="channel-icon ${key==='instagram'?'pink':key==='youtube'?'red':key==='blog'?'green':'yellow'}">${icon(ch.icon)}</span><div><strong>${esc(data.brand.accounts[key]||'계정명 미등록')}</strong><small>${data.brand.links[key]?'채널 주소 등록됨':'채널 주소 미등록'} · ${direct?'게시 권한 미연결':'관리자 직접 게시'}</small></div><button class="icon-btn" data-route="brand" aria-label="채널 계정 설정">${icon('settings')}</button></div><div class="field"><label for="publish-caption">${channel==='blog'?'블로그 본문':'게시글'} · 이 채널에만 적용</label><textarea id="publish-caption">${esc(captionFor())}</textarea></div><div class="review-list"><label><input id="review-product" type="checkbox"> 실제 제품 이미지와 문구를 확인했습니다.</label><label><input id="review-channel" type="checkbox"> 게시할 계정과 콘텐츠 이용 권한을 확인했습니다.</label></div><div class="notice">${icon('link')}${direct?'직접 게시 기능은 계정 인증과 서버 연결 후 활성화됩니다. 현재 외부로 전송되지 않습니다.':channel==='blog'?'본문·이미지를 받은 뒤 네이버 블로그에서 최종 게시하세요.':'채널 관리자에서 카드뉴스 소식을 등록하세요. 고객 메시지 발송은 별도입니다.'}</div><div class="publish-actions"><button class="btn primary full" data-act="publish-save">${icon('check')}게시 준비 저장</button>${direct?`<button class="btn full" disabled>${icon('lock')}${isVideo?'MP4 제작·계정 연결 후 게시':'계정 연결 후 바로 게시'}</button>`:''}<div class="two-actions"><button class="btn" data-act="copy">${icon('copy')}본문 복사</button><button class="btn" data-act="package-download">${icon('download')}${isVideo?'장면표 받기':'이미지 묶음 받기'}</button></div><a class="btn full" href="${managerLinks[channel]}" target="_blank" rel="noopener noreferrer">${ch.short} ${['blog','kakao','youtube'].includes(channel)?'관리자':'열기'} ${icon('external')}</a></div><p class="settings-note">준비 저장과 관리자 화면 열기는 게시 완료로 기록하지 않습니다.</p></section></div><section class="panel" style="margin-top:24px"><div class="flex between"><div><h2>채널별 준비 · 게시 기록</h2><p class="settings-note" style="margin-top:5px">직접 게시한 URL은 수동 기록으로 구분합니다.</p></div><button class="btn sm" data-act="manual-record">게시 URL 기록 ${icon('plus')}</button></div><div class="post-records">${posts.length?posts.map(p=>`<div class="post-row"><span class="channel-dot">${icon(channels.find(x=>x.id===p.channel).icon)}</span><strong>${channels.find(x=>x.id===p.channel).name}</strong><span class="badge ${p.url?'green':'yellow'}">${p.url?'수동 게시 기록':'게시 준비 저장'}</span><small>${new Date(p.at).toLocaleString('ko-KR',{timeZone:'Asia/Seoul'})}</small>${p.url?`<a href="${esc(p.url)}" target="_blank" rel="noopener noreferrer">게시물 보기 ${icon('external')}</a>`:'<span class="muted">외부 미전송</span>'}</div>`).join(''):'<div class="empty">이 캠페인에 저장된 게시 기록이 없습니다.</div>'}</div></section>`}
function downloadBlob(name,blob){const a=document.createElement('a'),u=URL.createObjectURL(blob);a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),2000)}
async function makeCanvas(index=cardIndex,fmt=channel){await document.fonts.ready;const scope=data;const im=await loadImage(prod().img),cv=document.createElement('canvas');if(data!==scope)throw Error('상품이 변경되어 생성을 취소했습니다.');paintCard(cv,selectedTemplate(),campaign().titles[index],im,selectedTemplate().subtitle,index,5,fmt);return cv}
downloadCard=async function(){try{const cv=await makeCanvas();const b=await new Promise(resolve=>cv.toBlob(resolve,'image/png'));if(!b)throw Error();downloadBlob(`${exportPrefix()}-${channel}-card-${cardIndex+1}.png`,b);toast('현재 디자인의 PNG를 저장했습니다.')}catch{toast('이미지를 저장하지 못했습니다. 원본 파일을 확인해 주세요.')}};
// Small uncompressed ZIP writer. A single download preserves card order and Korean text.
function crc32(bytes){let n=0xffffffff;for(const b of bytes){n^=b;for(let i=0;i<8;i++)n=(n>>>1)^((n&1)?0xedb88320:0)}return (n^0xffffffff)>>>0}
function makeZip(files){const enc=new TextEncoder(),parts=[],central=[];let offset=0;for(const file of files){const name=enc.encode(file.name),b=file.bytes,crc=crc32(b),local=new Uint8Array(30+name.length),v=new DataView(local.buffer);v.setUint32(0,0x04034b50,true);v.setUint16(4,20,true);v.setUint16(6,0x800,true);v.setUint32(14,crc,true);v.setUint32(18,b.length,true);v.setUint32(22,b.length,true);v.setUint16(26,name.length,true);local.set(name,30);parts.push(local,b);const c=new Uint8Array(46+name.length),d=new DataView(c.buffer);d.setUint32(0,0x02014b50,true);d.setUint16(4,20,true);d.setUint16(6,20,true);d.setUint16(8,0x800,true);d.setUint32(16,crc,true);d.setUint32(20,b.length,true);d.setUint32(24,b.length,true);d.setUint16(28,name.length,true);d.setUint32(42,offset,true);c.set(name,46);central.push(c);offset+=local.length+b.length}const len=central.reduce((n,c)=>n+c.length,0),end=new Uint8Array(22),e=new DataView(end.buffer);e.setUint32(0,0x06054b50,true);e.setUint16(8,files.length,true);e.setUint16(10,files.length,true);e.setUint32(12,len,true);e.setUint32(16,offset,true);return new Blob([...parts,...central,end],{type:'application/zip'})}
async function downloadPackage(button){const id=channel;if(['youtube','reels'].includes(id)){downloadText(`${exportPrefix()}-${id}-storyboard.txt`,campaign().name+'\n\n'+sceneTexts().map((t,i)=>`${['0–3초','3–8초','8–15초','15–20초'][i]}\n${t}`).join('\n\n')+'\n\n'+fullText(id)+'\n\n장면표 시안입니다. MP4 영상이 아닙니다.');return}button.disabled=true;const old=button.innerHTML;button.textContent='묶음 준비 중…';try{const files=[],count=id==='blog'?1:5;for(let i=0;i<count;i++){const cv=await makeCanvas(i,id),blob=await new Promise(r=>cv.toBlob(r,'image/png'));if(!blob)throw Error();files.push({name:`card-${String(i+1).padStart(2,'0')}.png`,bytes:new Uint8Array(await blob.arrayBuffer())})}files.push({name:'caption.txt',bytes:new TextEncoder().encode(fullText(id))});files.push({name:'readme.txt',bytes:new TextEncoder().encode('HooniWorks · 후니웍스\n상품: '+data.brand.name+'\n채널: '+channels.find(c=>c.id===id).name+'\n콘텐츠를 검토한 뒤 채널 관리자에서 직접 게시하세요.\n이 파일 다운로드는 실제 게시를 수행하지 않습니다.')});const archiveURL=URL.createObjectURL(makeZip(files));openModal('이미지 묶음이 준비됐어요',`<p class="intro">카드 ${count}장과 이 채널의 본문을 하나의 ZIP 파일로 묶었습니다.</p><a class="btn primary full" href="${archiveURL}" download="${exportPrefix()}-${id}-content.zip">ZIP 파일 다운로드</a><p class="settings-note">다운로드 후 각 채널의 관리자에서 게시할 수 있습니다.</p>`);setTimeout(()=>URL.revokeObjectURL(archiveURL),600000)}catch{toast('파일 묶음을 만들지 못했습니다. 사진을 확인해 주세요.')}finally{button.disabled=false;button.innerHTML=old}}
function savePublish(){if(!$('#review-product').checked||!$('#review-channel').checked){toast('제품·문구와 게시 계정 확인 항목을 체크해 주세요.');return}const c=campaign(),snapshot={campaignId:c.id,channel,at:new Date().toISOString(),caption:captionFor(),template:c.template,assetId:prod().id,status:'prepared'};const old=[...data.posts];data.posts=data.posts.filter(p=>!(p.campaignId===c.id&&p.channel===channel&&!p.url));data.posts.push(snapshot);if(!persist()){data.posts=old;return}render();toast('게시 준비를 저장했어요. 외부 채널에는 전송하지 않았습니다.')}
function manualRecord(){openModal('직접 게시한 콘텐츠 기록',`<p class="intro">${channels.find(c=>c.id===channel).name}에 직접 게시한 후 게시물 주소를 입력하세요. 자동 검증된 게시 결과와 구분해 보관합니다.</p><div class="field"><label for="manual-post-url">게시물 주소</label><input type="url" id="manual-post-url" placeholder="https://"></div><label class="check-line"><input id="manual-confirm" type="checkbox"> 해당 계정에 실제 게시한 콘텐츠입니다.</label>`,`<button class="btn" data-act="close-modal">취소</button><button class="btn primary" data-act="manual-save">수동 게시 기록 저장</button>`)}
document.addEventListener('click',async e=>{const el=e.target.closest('button,[data-act]');if(!el)return;let handled=true;const a=el.dataset.act;if(el.dataset.tFilter){templateFilter=el.dataset.tFilter;render()}else if(el.dataset.aFilter){assetFilter=el.dataset.aFilter;render()}else if(el.dataset.templateEdit)openTemplate(el.dataset.templateEdit);else if(el.dataset.assetDetail)assetDetail(el.dataset.assetDetail);else if(el.dataset.assetUse){const asset=allAssets().find(x=>x.id===el.dataset.assetUse);if(asset.role==='product'){campaign().assetId=asset.id;invalidate()}else{campaign().referenceAssetId=asset.id;persist()}navigate('studio');toast(asset.role==='product'?'제품 원본을 디자인에 적용했어요.':'디자인 참고 자료로 지정했어요.')}else if(el.dataset.assetRoleSave){const asset=data.uploads.find(x=>x.id===el.dataset.assetRoleSave),role=$('#asset-role-edit').value;asset.role=role;asset.type=roleNames[role];for(const c of data.campaigns){if(role!=='product'&&c.assetId===asset.id)delete c.assetId;if(role!=='reference'&&c.referenceAssetId===asset.id)delete c.referenceAssetId}persist();closeModal();render()}else if(el.dataset.authInfo)authInfo(el.dataset.authInfo);else if(a==='template-new')openTemplate();else if(a==='template-current')openTemplate(campaign().template,true);else if(a==='template-save'){if(!templateDraft.name.trim()){toast('템플릿 이름을 입력해 주세요.');return}const prev=[...data.templates],i=data.templates.findIndex(x=>x.id===templateDraft.id);if(i>=0){data.templates[i]={...templateDraft};for(const c of data.campaigns){if(c.template===templateDraft.id&&c.status==='승인 완료')c.status='검토 대기'}}else data.templates.push({...templateDraft});if(!persist()){data.templates=prev;return}closeModal();templateFilter='내 템플릿';navigate('templates');toast('내 템플릿에 저장했어요.')}else if(a==='asset-add')openUpload();else if(a==='asset-save')await saveUploads(el);else if(a==='brand-save-all')saveBrandAll();else if(a==='publish-open')navigate('publish');else if(a==='publish-save')savePublish();else if(a==='package-download')await downloadPackage(el);else if(a==='manual-record')manualRecord();else if(a==='manual-save'){try{const url=linkSafe($('#manual-post-url').value,profileKey(channel));if(!url||!$('#manual-confirm').checked){toast('게시물 주소와 실제 게시 확인이 필요합니다.');return}data.posts.push({campaignId:campaign().id,channel,url,status:'manual',at:new Date().toISOString()});if(!persist()){data.posts.pop();return}closeModal();render();toast('직접 게시한 URL을 수동 기록으로 저장했어요.')}catch(err){toast(err.message)}}else handled=false;if(handled){e.preventDefault();e.stopImmediatePropagation()}},true);
document.addEventListener('input',e=>{const t=e.target;if(t.dataset.tpl){templateDraft[t.dataset.tpl]=t.value;fillCanvases()}if(t.id==='template-search'){templateSearch=t.value;const list=allTemplates().filter(x=>(templateFilter==='전체'||templateFilter==='내 템플릿'&&x.custom||x.category===templateFilter)&&x.name.toLowerCase().includes(templateSearch.toLowerCase()));$('#template-results').innerHTML=list.map(templateTile).join('')||'<div class="empty">검색 결과가 없습니다.</div>';fillCanvases()}if(t.id==='edit-title')setTimeout(fillCanvases,0);if(['caption-edit','publish-caption'].includes(t.id)){campaign().channelCaptions||={};campaign().channelCaptions[channel]=t.value;invalidate();if($('#blog-text'))$('#blog-text').textContent=t.value;if($('.publish-caption'))$('.publish-caption').textContent=t.value;e.stopImmediatePropagation()}},true);
document.addEventListener('change',e=>{const t=e.target;if(t.dataset.tpl){templateDraft[t.dataset.tpl]=t.value;fillCanvases()}if(t.id==='studio-asset'){campaign().assetId=t.value;invalidate();render()}if(t.id==='studio-reference'){campaign().referenceAssetId=t.value;persist()}if(t.id==='publish-campaign'){current=t.value;channel=campaign().channels[0]||'instagram';render()}});
